/bin/zsh -lc "python3 -m unittest -v
 git diff --check
 git diff -- slug.py test_slug.py
python3 - <<'PY'
from slug import slugify
cases = {
    ' \\tHELLO\\n WORLD\\r ': 'hello-world',
    '--Hello--- \\tWorld--123--': 'hello-world-123',
    'ab,"'!cd'"': 'abcd',
    'A\\u00a0B': 'a-b',
    'İKABCé': 'abc',
}
for text, expected in cases.items():
    assert slugify(text) == expected, (text, expected)
for text in ('', ' \\t\\n', '"'!--! '"', 'éİK'):
    try:
        slugify(text)
    except ValueError:
        pass
    else:
        raise AssertionError(repr(text))
print('Self-review checks passed: 5 normalization cases and 4 empty-result cases.')
PY"

